#!/bin/sh
# abcd's UserPromptSubmit hook. hooks/hooks.json runs this file with sh, so the host's
# hook-error line names this short command rather than the whole script.
r="${CLAUDE_PLUGIN_ROOT:-}"; [ -n "$r" ] || exit 0; z=""; case "${HOME:-}" in /*) if [ -e "$HOME/.abcd" ] || [ -L "$HOME/.abcd" ]; then z=1; fi ;; esac; if [ -n "$z" ]; then if [ -f "$r/abcd" ] && [ -x "$r/abcd" ]; then exec "$r/abcd" hook prompt-router; fi; if [ -e "$HOME/.abcd.noindex" ] || [ -L "$HOME/.abcd.noindex" ]; then printf '%s\n' 'abcd: Both ~/.abcd and ~/.abcd.noindex exist, so abcd has written nothing and moves neither. Keep the one you want, named ~/.abcd.noindex, and take the other out of your home folder, reconnect the working copies kept there with `find ~/.abcd.noindex/worktrees -type d -exec test -e {}/.git \; -prune -exec test -f {}/.git \; -exec git -C {} worktree repair \;` (each `repair: gitdir incorrect` line it prints is a link it fixed), then run abcd again.' >&2; else printf '%s\n' 'abcd: abcd'\''s folder is now ~/.abcd.noindex, a name the Mac'\''s search indexer passes over, and ~/.abcd still stands, so abcd has written nothing. Rename it with `mv ~/.abcd ~/.abcd.noindex`, reconnect the working copies kept there with `find ~/.abcd.noindex/worktrees -type d -exec test -e {}/.git \; -prune -exec test -f {}/.git \; -exec git -C {} worktree repair \;` (each `repair: gitdir incorrect` line it prints is a link it fixed), then run abcd again.' >&2; fi; exit 1; fi; if [ ! -x "$r/abcd" ] && [ -x "$r/hooks/bootstrap.sh" ] && [ -z "$(find "$r/.bootstrap.attempt" -maxdepth 0 -mmin -10 2>/dev/null)" ]; then : > "$r/.bootstrap.attempt" 2>/dev/null || true; "$r/hooks/bootstrap.sh" --unseen >/dev/null 2>&1 </dev/null || true; fi; g=""; [ -x "$r/abcd" ] && g="$r/abcd"; if [ -z "$g" ]; then c=$(command -v abcd 2>/dev/null); if [ -n "$c" ]; then y=""; case "$c" in /*) dd=${c%/*}; [ -n "$dd" ] || dd=/; d=$(cd -P "$dd" 2>/dev/null && pwd -P); if [ -z "$d" ]; then y="its directory could not be resolved"; else q=$(pwd -P); case "$d/" in "$q"/*) y="it lives inside the working tree" ;; esac; fi; if [ -z "$y" ]; then case "$(/bin/ls -ld "$d" 2>/dev/null)" in ????????w*) y="its directory is world-writable" ;; esac; fi; if [ -z "$y" ]; then case "$(/bin/ls -ldL "$c" 2>/dev/null)" in ????????w*) y="the binary itself is world-writable" ;; esac; fi ;; *) y="it did not resolve to an absolute path" ;; esac; if [ -z "$y" ]; then o=""; w=""; e="${HOME:-}/.abcd.noindex/path-entry"; if [ -n "${HOME:-}" ] && [ -f "$e" ]; then if [ -L "${HOME}/.abcd.noindex" ]; then w=2; elif [ -n "$(find "$e" -maxdepth 0 -type f -user "$(id -un 2>/dev/null)" ! -perm -0020 ! -perm -0002 2>/dev/null)" ]; then while IFS= read -r ln || [ -n "$ln" ]; do case "$ln" in path=*) if [ "${ln#path=}" = "$c" ]; then o=1; fi ;; esac; done < "$e"; else w=1; fi; fi; if [ "$w" = 2 ]; then y="~/.abcd.noindex is a symlink, so its path-entry record is not read (replace the link with a real directory)"; elif [ -n "$w" ]; then y="its ~/.abcd.noindex/path-entry record is not owned by you or is writable by others"; else [ -n "$o" ] || y="~/.abcd.noindex/path-entry does not record it as the abcd installed here"; fi; fi; if [ -n "$y" ]; then p=$(printf '%s' "$c" | tr -d '\000-\037\177'); printf '%s\n' "abcd: ignoring the abcd found on PATH at $p because $y — a hook runs only the abcd recorded in ~/.abcd.noindex/path-entry by the documented install, from an ordinary user directory such as ~/.local/bin that neither the project nor another local user can replace; re-run the install per https://github.com/intentdriven/abcd#install to record it" >&2; else g="$c"; fi; fi; fi; if [ -n "$g" ]; then exec "$g" hook prompt-router; fi; printf '%s\n' "abcd: the plugin binary is missing and could not be provisioned, so the rules loader is inactive for this prompt — hooks/bootstrap.sh installs it when the session has network access, or install per https://github.com/intentdriven/abcd#install" >&2; exit 1
